<template>
  <main class="writing-page">
    <DocumentStudioChrome :current="completed ? 5 : 4" :project-name="projectName" :busy="running || starting" :assistant-items="assistantItems" :description="completed ? '文档已完成，所有检查项均可在成果区查看。' : '我会持续汇报文献读取、素材匹配、章节写作和格式规范状态。'" />
    <header><span>STEP 4 · AI WRITING STUDIO</span><h1>AI正文生成中心</h1><p>基于已确认的文献、章节与素材，逐章生成完整专业文档。</p></header>

    <section class="project-overview panel">
      <div class="project-identity"><small>当前项目</small><h2>{{ projectName }}</h2><p>{{ professionalType }} · {{ stage }}</p><div class="context-stats"><span>专业类型<b>{{ professionalType }}</b></span><span>章节数量<b>{{ chapters.length }}</b></span><span>图片数量<b>{{ imageCount }}</b></span><span>文献数量<b>{{ referenceCount }}</b></span></div></div>
      <div class="overall-progress"><div><span>当前阶段</span><b>{{ statusLabel }}</b></div><strong>{{ progress }}<small>%</small></strong><div class="progress-track"><i :style="{width:`${progress}%`}"></i></div></div>
    </section>

    <section class="writing-grid">
      <div class="writing-main">
        <section class="control-card panel">
          <div class="section-head"><div><small>GENERATION CONTROL</small><h2>生成控制中心</h2></div><span>{{ running ? 'AI 正在写作' : completed ? '生成完成' : '准备就绪' }}</span></div>
          <div class="output-items"><div v-for="(item,index) in outputItems" :key="item" :class="checkState(index)"><i>{{ checkState(index)==='done'?'✓':checkState(index)==='active'?'●':'○' }}</i><span>{{ item }}</span><small>{{ checkStateText(index) }}</small></div></div>
          <button v-if="!running&&!completed" class="primary-action" type="button" :disabled="starting" @click="start">{{ starting ? '正在启动…' : failed ? '重新开始生成' : '开始生成' }}</button>
          <button v-else-if="running" class="primary-action running-button" type="button" disabled>生成中</button>
          <button v-else-if="completed" class="primary-action" type="button" @click="scrollResult">查看结果</button>
          <div v-if="running" class="active-task"><i></i><div><b>{{ stage }}</b><span>{{ displayMessage }}</span></div></div>
          <div v-if="failed" class="soft-warning"><b>任务已暂停</b><p>{{ displayMessage }}。可以调整后重新生成，格式类问题将自动修复。</p></div>
        </section>

        <section class="chapter-progress panel">
          <div class="section-head"><div><small>CHAPTER PROGRESS</small><h2>章节级进度</h2></div><span>{{ completedChapters }}/{{ chapters.length }} 章完成</span></div>
          <div class="chapter-list"><article v-for="(chapter,index) in chapters" :key="chapter.id || index" :class="chapterStatus(index)"><i>{{ chapterStatus(index)==='done' ? '✓' : index+1 }}</i><div class="chapter-copy"><b>第 {{ chapter.chapter_no || index+1 }} 章 · {{ cleanTitle(chapter.title) }}</b><span><small>{{ chapter.target_word_count || sectionWords(chapter) }} 字</small><small>{{ chapterReferenceCount(chapter) }} 条引用</small><small>{{ chapterImageCount(chapter) }} 张图片</small></span></div><em>{{ chapterStatusText(index) }}</em><div class="chapter-line"><span :style="{width:`${chapterProgress(index)}%`}"></span></div></article></div>
        </section>

        <section class="live-log panel">
          <div class="section-head"><div><small>LIVE AI LOG</small><h2>实时 AI 日志</h2></div><span class="live-dot">{{ running ? '实时更新' : '任务记录' }}</span></div>
          <div class="log-list"><div v-for="item in logItems" :key="item.label" :class="item.state"><i>{{ item.state==='done'?'✓':item.state==='active'?'···':'○' }}</i><span><b>{{ item.label }}</b><small>{{ item.message }}</small></span><time>{{ item.state==='done'?'已完成':item.state==='active'?'进行中':'等待' }}</time></div></div>
        </section>
      </div>

      <aside class="writing-side">
        <section class="basis-card panel"><small>WRITING BASIS</small><h3>生成依据</h3><div><span>参考文献<b>{{ referenceCount }}</b></span><span>确认图片<b>{{ imageCount }}</b></span><span>配置表格<b>{{ tableCount }}</b></span><span>章节数量<b>{{ chapters.length }}</b></span></div></section>
        <section class="quality-card panel"><small>QUALITY CHECK</small><h3>自动质量规范</h3><ul><li v-for="item in qualityItems" :key="item.label"><i>{{ completed?'✓':running?'···':'○' }}</i><span><b>{{ item.label }}</b><small>{{ completed?'已完成':running?'正在规范':'等待检查' }}</small></span></li></ul><p>格式问题不会阻断任务，系统会在导出前自动规范。</p></section>
      </aside>
    </section>

    <section v-if="completed" id="export" class="result-card panel">
      <div class="docx-icon">W</div><div><small>FINAL DOCUMENT</small><h2>{{ projectName }}.docx</h2><p>正文、图片、图注、表格与参考文献已合并完成。</p><div class="result-checks"><span v-for="item in qualityItems" :key="item.label">✓ {{ item.label }}</span></div></div><div class="result-actions"><button type="button" @click="preview">在线预览</button><button class="primary-action" type="button" @click="download">下载 DOCX</button></div>
    </section>
  </main>
</template>

<script setup>
import { computed, onMounted, onUnmounted, ref } from 'vue'
import { ElMessage } from 'element-plus'
import { useRouter } from 'vue-router'
import DocumentStudioChrome from '../../components/DocumentStudioChrome.vue'
import { downloadArtifact, getWritingProgress, getWritingV2Flow, startWritingGeneration } from '../../api/rewrite'

const router=useRouter();const id=sessionStorage.getItem('dropai_writing_project_id')||''
const flow=ref({chapters:[],materials:[],references:[]});const starting=ref(false);const status=ref('WAITING');const stage=ref('等待开始');const progress=ref(0);const message=ref('项目依据已确认，可以开始生成。');const downloadUrl=ref('');let timer=null
const outputItems=['章节正文','图片插入','图注','表格','参考文献'];const qualityItems=[{label:'章节完整'},{label:'图片引用'},{label:'GB/T 7714'},{label:'排版规范'}]
const running=computed(()=>status.value==='RUNNING');const completed=computed(()=>status.value==='SUCCESS');const failed=computed(()=>status.value==='FAILED')
const chapters=computed(()=>flow.value.chapters||[]);const projectName=computed(()=>flow.value.project_name||flow.value.project_title||flow.value.title||flow.value.topic||sessionStorage.getItem('dropai_writing_project_title')||'未命名项目');const professionalType=computed(()=>({environment:'环境设计',visual_communication:'视觉传达',interior_design:'室内设计',general:'普通论文'})[flow.value.document_mode]||'普通论文')
const referenceCount=computed(()=>Number(flow.value.reference_count||flow.value.references?.length||0));const imageCount=computed(()=>flow.value.materials?.filter(item=>Boolean(item.is_confirmed)).length||0);const tableCount=computed(()=>(flow.value.chapters||[]).reduce((sum,chapter)=>sum+(chapter.tables?.length||0),0));const completedChapters=computed(()=>chapters.value.filter((_,index)=>chapterStatus(index)==='done').length)
const statusLabel=computed(()=>completed.value?'生成完成':failed.value?'等待重试':running.value?'正文生成中':'准备生成');const displayMessage=computed(()=>/(一级标题|二级标题|标题样式|编号样式|质量检查未通过)/.test(message.value||'')?'检测到格式差异，系统正在自动规范，不会中断生成。':message.value)
const assistantItems=computed(()=>[{label:'整体进度',value:`${progress.value}%`},{label:'当前章节',value:currentChapterLabel.value},{label:'完成章节',value:`${completedChapters.value}/${chapters.value.length}`},{label:'质量规范',value:completed.value?'已完成':running.value?'进行中':'待执行'}])
const currentChapterIndex=computed(()=>Math.min(Math.max(0,Math.floor((progress.value/100)*Math.max(chapters.value.length,1))),Math.max(chapters.value.length-1,0)));const currentChapterLabel=computed(()=>chapters.value.length?`第 ${chapters.value[currentChapterIndex.value]?.chapter_no||currentChapterIndex.value+1} 章`:'等待章节')
const logItems=computed(()=>{const p=progress.value;return[{label:'文献读取',message:`读取 ${referenceCount.value} 篇参考文献`,state:p>=15||completed.value?'done':running.value?'active':'waiting'},{label:'图片匹配',message:`匹配 ${imageCount.value} 张已确认图片`,state:p>=30||completed.value?'done':p>=15&&running.value?'active':'waiting'},{label:'章节生成',message:currentChapterLabel.value,state:completed.value?'done':p>=30&&running.value?'active':'waiting'},{label:'格式检查',message:'标题、引用与排版自动规范',state:completed.value?'done':p>=85&&running.value?'active':'waiting'}]})
function chapterProgress(index){if(completed.value)return 100;const unit=100/Math.max(chapters.value.length,1);return Math.max(0,Math.min(100,(progress.value-index*unit)/unit*100))}
function chapterStatus(index){const value=chapterProgress(index);return value>=100?'done':value>0?'active':'waiting'}function chapterStatusText(index){return({done:'完成',active:'生成中',waiting:'等待'})[chapterStatus(index)]}
function checkState(index){if(completed.value)return'done';if(!running.value)return'waiting';const threshold=[8,22,38,70,86][index]||0;const next=[22,38,70,86,101][index]||101;return progress.value>=next?'done':progress.value>=threshold?'active':'waiting'}
function checkStateText(index){return({waiting:'未开始',active:'处理中',done:'完成'})[checkState(index)]}
function sectionWords(chapter){return(chapter.sections||[]).reduce((sum,section)=>sum+Number(section.target_word_count||0),0)}
function chapterReferenceCount(chapter){return Number(chapter.reference_count||chapter.citation_count||0)}
function chapterImageCount(chapter){return Number(chapter.image_count||(chapter.sections||[]).reduce((sum,section)=>sum+Number(section.image_count||0),0))}
function scrollResult(){router.push('/writing-generator/export')}
function cleanTitle(value){return String(value||'').replace(/^\d+(\.\d+)?\s*/,'').replace(/^第[一二三四五六七八九十\d]+章\s*/,'')}
async function load(){if(!id){ElMessage.warning('项目不存在');return router.push('/writing-generator')}flow.value=await getWritingV2Flow(id);try{const data=await getWritingProgress(id);applyProgress(data);if(status.value==='RUNNING')poll()}catch{}}
async function start(){if(!id)return router.push('/writing-generator');starting.value=true;try{await startWritingGeneration(id);status.value='RUNNING';stage.value='正在读取项目依据';progress.value=Math.max(progress.value,1);poll()}finally{starting.value=false}}
function applyProgress(data){status.value=data.status||status.value;stage.value=data.current_stage||stage.value;progress.value=Number(data.progress||0);message.value=data.error_message||data.message||message.value;downloadUrl.value=data.files?.[0]?.download_url||downloadUrl.value}
function poll(){clearInterval(timer);timer=setInterval(async()=>{const data=await getWritingProgress(id);applyProgress(data);if(['SUCCESS','FAILED'].includes(status.value))clearInterval(timer)},1800)}
async function getArtifact(){if(!downloadUrl.value)throw new Error('DOCX 文件尚未就绪');return downloadArtifact(downloadUrl.value)}
async function download(){try{const blob=await getArtifact();const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download=`${projectName.value.replace(/[\\/:*?"<>|]/g,'_')}.docx`;a.click();URL.revokeObjectURL(url)}catch(error){ElMessage.warning(error.message)}}
async function preview(){try{const blob=await getArtifact();const url=URL.createObjectURL(blob);window.open(url,'_blank','noopener,noreferrer');setTimeout(()=>URL.revokeObjectURL(url),60000)}catch(error){ElMessage.warning(error.message)}}
onMounted(load);onUnmounted(()=>clearInterval(timer))
</script>

<style scoped>
