px;padding:11px;border-radius:10px;background:#faf9ff;color:#646877;font-size:11px}.output-items i{color:#145b4d;font-style:normal}.primary-action{padding:12px 20px;border:0;border-radius:10px;background:linear-gradient(135deg,#6e4fff,#ff55b0);color:#fff;font-weight:700;box-shadow:0 8px 22px rgba(110,79,255,.18)}.control-card>.primary-action{width:100%}.active-task{display:flex;align-items:center;gap:12px;padding:13px;border-radius:11px;background:#f4f1ff}.active-task>i,.live-dot:before{width:8px;height:8px;border-radius:50%;background:#6e4fff;box-shadow:0 0 0 5px #e9e3ff;content:""}.active-task div{display:grid}.active-task span{color:#777b89;font-size:11px}.soft-warning{margin-top:12px;padding:12px;border-radius:10px;background:#fff5e9;color:#9a691f}.soft-warning p{margin:4px 0 0;font-size:11px}.chapter-list{display:grid;gap:8px;margin-top:16px}.chapter-list article{position:relative;display:grid;grid-template-columns:32px 1fr auto;align-items:center;gap:11px;padding:12px 12px 17px;border:1px solid #eeeaf8;border-radius:11px}.chapter-list article>i{display:grid;place-items:center;width:29px;height:29px;border-radius:9px;background:#f2eff8;color:#8f93a0;font-style:normal}.chapter-list article.active{border-color:#cbbfff;background:#fbfaff}.chapter-list article.active>i{background:#6e4fff;color:#fff}.chapter-list article.done>i{background:#e7f3ef;color:#145b4d}.chapter-list article>div{display:grid}.chapter-list article span,.chapter-list article em{color:#858997;font-size:10px;font-style:normal}.chapter-list article.active em{color:#6e4fff}.chapter-line{position:absolute!important;right:12px;bottom:7px;left:54px;height:3px;overflow:hidden;border-radius:9px;background:#efedf5}.chapter-line span{display:block;height:100%;background:linear-gradient(90deg,#6e4fff,#ff55b0)}.log-list{display:grid;gap:4px;margin-top:15px}.log-list>div{display:grid;grid-template-columns:26px 1fr auto;align-items:center;gap:10px;padding:10px;border-radius:9px}.log-list>div.active{background:#f7f4ff}.log-list i{display:grid;place-items:center;width:22px;height:22px;border-radius:50%;background:#f0eef5;color:#999daa;font-style:normal}.log-list .done i{background:#e7f3ef;color:#145b4d}.log-list .active i{background:#ebe5ff;color:#6e4fff}.log-list span{display:grid}.log-list small,.log-list time{color:#9296a2;font-size:9px}.live-dot{display:flex;align-items:center;gap:8px}.basis-card h3,.quality-card h3{margin:5px 0 14px}.basis-card>div{display:grid;grid-template-columns:1fr 1fr;gap:8px}.basis-card span{display:grid;gap:5px;padding:12px;border-radius:10px;background:#faf9ff;color:#858997;font-size:9px}.basis-card span b{color:#5d48b6;font-size:22px}.quality-card ul{display:grid;gap:10px;margin:0;padding:0;list-style:none}.quality-card li{display:flex;gap:8px}.quality-card li i{display:grid;place-items:center;width:22px;height:22px;border-radius:50%;background:#f0edf8;color:#6e4fff;font-style:normal}.quality-card li span{display:grid}.quality-card li small{color:#9296a2;font-size:9px}.quality-card>p{margin:15px 0 0;padding:11px;border-radius:9px;background:#fff6e9;color:#91651f;font-size:10px;line-height:1.5}.result-card{display:grid;grid-template-columns:60px 1fr auto;align-items:center;gap:17px}.docx-icon{display:grid;place-items:center;width:54px;height:64px;border-radius:10px;background:#6e4fff;color:#fff;font-size:24px;font-weight:800}.result-card h2{margin:5px 0}.result-card p{margin:0;color:#777b89}.result-checks{display:flex;flex-wrap:wrap;gap:6px;margin-top:10px}.result-checks span{padding:5px 8px;border-radius:99px;background:#eaf5f1;color:#145b4d;font-size:9px}.result-actions{display:flex;gap:8px}.result-actions>button:not(.primary-action){padding:11px 15px;border:1px solid #ad99f6;border-radius:10px;background:#fff;color:#6e4fff}@media(max-width:1500px){.writing-page{padding-right:40px}.writing-grid{grid-template-columns:1fr}.writing-side{display:grid;grid-template-columns:1fr 1fr;gap:16px}.writing-side .panel{margin-top:0}}@media(max-width:900px){.writing-page{padding:0 12px 35px}.project-overview,.result-card{align-items:stretch;grid-template-columns:1fr;flex-direction:column}.overall-progress{width:100%}.output-items{grid-template-columns:1fr 1fr}.writing-side{grid-template-columns:1fr}.result-actions{flex-direction:column}}
.project-identity{min-width:0;flex:1}.context-stats{display:flex;flex-wrap:wrap;gap:7px;margin-top:14px}.context-stats span{display:grid;gap:2px;min-width:86px;padding:8px 10px;border:1px solid #eeeaf8;border-radius:9px;background:#faf9ff;color:#9094a0;font-size:8px}.context-stats b{color:#5d48b6;font-size:11px}.output-items>div{display:grid;grid-template-columns:auto 1fr;gap:2px 7px}.output-items>div small{grid-column:2;color:#999da8;font-size:8px}.output-items>div.waiting{background:#f5f5f7;color:#858997}.output-items>div.waiting i{color:#a4a7af}.output-items>div.active{background:#f1edff;color:#6e4fff}.output-items>div.active i{color:#6e4fff}.output-items>div.done{background:#eaf5f1;color:#145b4d}.output-items>div.done i{color:#145b4d}.running-button{opacity:.78;cursor:wait}.chapter-copy{display:grid;gap:5px}.chapter-copy>span{display:flex;flex-wrap:wrap;gap:6px}.chapter-copy>span small{padding:3px 6px;border-radius:6px;background:#f5f3fa;color:#7d8190;font-size:8px}.chapter-list article.active .chapter-copy>span small{background:#eee9ff;color:#7059c8}@media(max-width:900px){.context-stats{display:grid;grid-template-columns:1fr 1fr}}
</style>
